import type {Block, BlockType, Note} from "@/types/Note";
import type {Folder} from "@/services/FolderService";

interface StoredFolder {
    id: string;
    name: string;
    parent_id: string | null;
}

interface StoredNote {
    id: string;
    title: string;
    folder_id: string | null;
    blocks: Block[];
}

const LATENCY_MS = 40;

const folders = new Map<string, StoredFolder>();
const notes = new Map<string, StoredNote>();

let seq = 0;
const nextId = (prefix: string) => `${prefix}-${(++seq).toString().padStart(4, "0")}`;

const now = () => new Date().toISOString();

function textBlock(index: number, text: string): Block {
    return {
        id: nextId("block"),
        type: "text",
        index,
        content: {text},
        created_at: now(),
        updated_at: now(),
    };
}

function seedFolder(name: string, parentId: string | null): string {
    const id = nextId("folder");
    folders.set(id, {id, name, parent_id: parentId});
    return id;
}

function seedNote(title: string, folderId: string | null, blocks: Block[]): string {
    const id = nextId("note");
    notes.set(id, {id, title, folder_id: folderId, blocks});
    return id;
}

const PARAGRAPHS = `First paragraph, plain prose that should wrap naturally when it is long enough to exceed the measure of the column it is set in.

Second paragraph after a hard break.

Third paragraph.
Soft break inside the same paragraph.`;

const UNORDERED = `- Level one item
- Second level one item
    - Nested level two
    - Another level two
        - Level three
- Back to level one`;

const ORDERED = `1. First
2. Second
    1. Nested first
    2. Nested second
        1. Deep first
3. Third`;

const MIXED = `1. Ordered parent
    - Unordered child
    - Another child
        1. Ordered grandchild
2. Second ordered

- Unordered parent
    1. Ordered child`;

const HEADINGS = `# Heading one

Paragraph under h1.

## Heading two

Paragraph under h2.

### Heading three

Paragraph under h3.

## Heading straight after paragraph

Trailing paragraph.`;

const INLINE = `Inline \`code\`, **bold**, *italic*, and a [link](https://example.com).

> A blockquote that should sit flush with the text column.

---

Paragraph after a rule.

- List item directly before a paragraph

Paragraph directly after a list.`;

const SHORTEST_PATHS = `# Shortest paths

The greedy argument only works because edge weights are non-negative. Once a vertex is popped off the priority queue its distance is final.

- Dijkstra: non-negative weights, \`O((V + E) log V)\` with a binary heap
- Bellman-Ford: handles negative edges, detects negative cycles
- Floyd-Warshall: all pairs, \`O(V^3)\`, trivially easy to write

> The proof is an exchange argument: assume a shorter path exists, then show it must pass through an unvisited vertex whose tentative distance is already larger.`;

const AMORTIZED = `## Three methods

1. Aggregate — total cost over *n* operations, divided by *n*
2. Accounting — overcharge cheap operations to pay for expensive ones
3. Potential — define a function over the data structure's state

The dynamic array doubling argument is the canonical example.`;

function seed() {

    const coursework = seedFolder("Coursework", null);
    const cs341 = seedFolder("CS 341", coursework);
    seedFolder("STAT 231", coursework);
    const journal = seedFolder("Journal", null);
    seedFolder("Archive", null);

    seedNote("Dijkstra and friends", cs341, [
        textBlock(0, SHORTEST_PATHS),
        textBlock(1, "## Where it breaks\n\nNegative edges break the invariant that the minimum tentative distance is final."),
    ]);

    seedNote("Amortized analysis", cs341, [textBlock(0, AMORTIZED)]);

    seedNote("Reading list", journal, [
        textBlock(0, "Books I keep meaning to finish.\n\n- *The Design of Everyday Things*\n- *Thinking in Systems*\n- *A Philosophy of Software Design*"),
    ]);

    const scenarios = seedFolder("Rendering scenarios", null);
    seedNote("Paragraphs", scenarios, [textBlock(0, PARAGRAPHS)]);
    seedNote("Unordered lists", scenarios, [textBlock(0, UNORDERED)]);
    seedNote("Ordered lists", scenarios, [textBlock(0, ORDERED)]);
    seedNote("Mixed nesting", scenarios, [textBlock(0, MIXED)]);
    seedNote("Headings and spacing", scenarios, [textBlock(0, HEADINGS)]);
    seedNote("Inline and blocks", scenarios, [textBlock(0, INLINE)]);

    seedNote("Code blocks", scenarios, [
        textBlock(0, "A code block is its own block type now, not an inline fence."),
        {
            id: nextId("block"),
            type: "code",
            index: 1,
            content: {code: "func main() {\n\tfmt.Println(\"hello\")\n}", language: "go"},
            created_at: now(),
            updated_at: now(),
        },
        textBlock(2, "Text continues after it."),
    ]);

    seedNote("Image blocks", scenarios, [
        textBlock(0, "Paste an image in a text block and it becomes its own block below."),
        {
            id: nextId("block"),
            type: "image",
            index: 1,
            content: {url: "data:image/png;base64,", strokes: []},
            created_at: now(),
            updated_at: now(),
        },
    ]);

    seedNote("Scratch", null, [textBlock(0, "Anything that does not have a home yet.")]);
}

// ?empty=1 leaves the library unseeded: the first-run sidebar is a different render branch, and the
// only one where the cloud setup entry point actually has to be found.
if (!new URLSearchParams(window.location.search).has("empty")) seed();

const delay = <T, >(value: T): Promise<T> =>
    new Promise(resolve => setTimeout(() => resolve(value), LATENCY_MS));

const fail = (message: string): never => {
    throw new Error(message);
};

function toNote(stored: StoredNote): Note {
    return {
        id: stored.id,
        title: stored.title,
        folder_id: stored.folder_id,
        blocks: [...stored.blocks].sort((a, b) => a.index - b.index),
    };
}

function buildFolder(id: string): Folder {
    const stored = folders.get(id) ?? fail(`folder not found: ${id}`);
    return {
        id: stored.id,
        name: stored.name,
        parent_id: stored.parent_id,
        children: [...folders.values()]
            .filter(f => f.parent_id === id && f.id !== id)
            .map(f => buildFolder(f.id)),
        notes: [...notes.values()]
            .filter(n => n.folder_id === id)
            .map(toNote),
    };
}

// Mirrors folder.tree on the Go side: a synthesized root over everything with no parent.
function buildTree(): Folder {
    return {
        id: "",
        name: "",
        parent_id: null,
        children: [...folders.values()].filter(f => f.parent_id === null).map(f => buildFolder(f.id)),
        notes: [...notes.values()].filter(n => n.folder_id === null).map(toNote),
    };
}

function descendantFolderIds(id: string): string[] {
    const direct = [...folders.values()].filter(f => f.parent_id === id && f.id !== id);
    return direct.flatMap(f => [f.id, ...descendantFolderIds(f.id)]);
}

function normalizeContent(type: BlockType, content: unknown): Block["content"] {
    if (typeof content === "string") {
        return type === "canvas" ? {data: {}} : {text: content};
    }
    if (content && typeof content === "object") {
        return content as Block["content"];
    }
    return type === "canvas" ? {data: {}} : {text: ""};
}

let cloudHost: string | null = null;

// Must stay identical to maskedHost in electron/cloudConfig.js: the project ref is the label worth
// hiding, and a mock that hides a different one verifies a fiction.
function maskHost(host: string): string {
    const labels = host.split(".");
    if (labels.length < 2) return `${labels[0].slice(0, 2)}***`;
    if (labels.length === 2) return host;
    return ["***", ...labels.slice(-2)].join(".");
}

export function installMockBridge() {
    const bridge = {
        local: {
            folder: {
                create: (payload: { name: string; parent_id: string | null }) => {
                    const parentId = payload.parent_id || null;
                    if (parentId !== null && !folders.has(parentId)) fail(`folder not found: ${parentId}`);
                    const siblings = [...folders.values()].filter(f => f.parent_id === parentId);
                    if (siblings.some(f => f.name === payload.name)) {
                        fail(`a folder named "${payload.name}" already exists here`);
                    }
                    const id = nextId("folder");
                    folders.set(id, {id, name: payload.name, parent_id: parentId});
                    return delay(buildFolder(id));
                },
                get: (id: string) => delay(buildFolder(id)),
                tree: () => delay(buildTree()),
                update: (payload: { current_id: string; name?: string; parent_id?: string | null }) => {
                    const stored = folders.get(payload.current_id) ?? fail(`folder not found: ${payload.current_id}`);
                    if (payload.name !== undefined) stored.name = payload.name;
                    if (payload.parent_id !== undefined) {
                        const target = payload.parent_id || null;
                        if (target !== null && (target === stored.id || descendantFolderIds(stored.id).includes(target))) {
                            fail("cannot move a folder into itself");
                        }
                        stored.parent_id = target;
                    }
                    return delay(buildFolder(stored.id));
                },
                delete: (id: string) => {
                    const doomed = [id, ...descendantFolderIds(id)];
                    doomed.forEach(folderId => {
                        folders.delete(folderId);
                        [...notes.values()]
                            .filter(n => n.folder_id === folderId)
                            .forEach(n => notes.delete(n.id));
                    });
                    return delay(undefined);
                },
            },
            note: {
                create: (payload: { title: string; folder_id: string | null }) => {
                    const folderId = payload.folder_id || null;
                    if (folderId !== null && !folders.has(folderId)) fail(`folder not found: ${folderId}`);
                    const id = nextId("note");
                    notes.set(id, {id, title: payload.title, folder_id: folderId, blocks: []});
                    return delay(toNote(notes.get(id)!));
                },
                get: (id: string) => delay(toNote(notes.get(id) ?? fail(`note not found: ${id}`))),
                update: (payload: {
                    id: string;
                    title?: string;
                    folder_id?: string;
                    blocks?: Array<{ id: string; index: number }>
                }) => {
                    const stored = notes.get(payload.id) ?? fail(`note not found: ${payload.id}`);
                    if (payload.title !== undefined) stored.title = payload.title;
                    if (payload.folder_id !== undefined) stored.folder_id = payload.folder_id;
                    payload.blocks?.forEach(({id, index}) => {
                        const block = stored.blocks.find(b => b.id === id);
                        if (block) block.index = index;
                    });
                    return delay(toNote(stored));
                },
                delete: (id: string) => {
                    notes.delete(id);
                    return delay(undefined);
                },
            },
            block: {
                create: (noteId: string, payload: { type: BlockType; index: number; content: unknown }) => {
                    const stored = notes.get(noteId) ?? fail(`note not found: ${noteId}`);
                    const block: Block = {
                        id: nextId("block"),
                        type: payload.type,
                        index: payload.index,
                        content: normalizeContent(payload.type, payload.content),
                        created_at: now(),
                        updated_at: now(),
                    };
                    stored.blocks.push(block);
                    return delay(block);
                },
                update: (noteId: string, blockId: string, payload: { type: BlockType; content: unknown }) => {
                    const stored = notes.get(noteId) ?? fail(`note not found: ${noteId}`);
                    const block = stored.blocks.find(b => b.id === blockId) ?? fail(`block not found: ${blockId}`);
                    block.type = payload.type ?? block.type;
                    block.content = normalizeContent(block.type, payload.content);
                    block.updated_at = now();
                    return delay(block);
                },
                delete: (noteId: string, blockId: string) => {
                    const stored = notes.get(noteId) ?? fail(`note not found: ${noteId}`);
                    stored.blocks = stored.blocks.filter(b => b.id !== blockId);
                    return delay(undefined);
                },
            },
            sync: {
                focus: (noteId: string | null) => delay({note_id: noteId ?? ""}),
            },
            asset: {
                uploadImage: (payload: { filename: string; data_base64: string }) =>
                    delay({url: `data:image/png;base64,${payload.data_base64}`, filename: payload.filename}),
            },
        },
        // Mirrors main's contract rather than storing anything: the password goes in and never
        // comes back, so the dev harness cannot accidentally prove a leak impossible.
        cloud: {
            configure: (config: { host: string }) => {
                if (!config || !config.host) fail("Missing host");
                cloudHost = config.host;
                return delay({configured: true, host: maskHost(cloudHost)});
            },
            status: () => delay(cloudHost
                ? {configured: true, host: maskHost(cloudHost)}
                : {configured: false, host: null}),
            clear: () => {
                cloudHost = null;
                return delay({configured: false, host: null});
            },
        },
    };

    (window as unknown as { noteblock: unknown }).noteblock = bridge;
    console.info("[noteblock] dev mock bridge installed — no Electron preload detected");
}
